import { readClaimableEth } from './claims.js';
import { readCoinflipDisplaySnapshot } from './coinflip.js';
import { readAfkingFunding } from './passes.js';
import { readNativeBalance } from './read-provider.js';
import { purchaseFundingPayment } from './lootbox.js';
import { RECORD_KIND_BUY, RECORD_KIND_FLIP, RECORD_KIND_LUCKBOX } from './records.js';

function amount(value) {
  if (value == null) return null;
  try { return BigInt(value) >= 0n ? BigInt(value) : null; }
  catch (_) { return null; }
}

/** Account-scoped, spendable sources; failed reads never retain old balances. */
export async function readRecordBountyFunds(address) {
  const reads = await Promise.allSettled([
    readNativeBalance(address, { fresh: true }),
    readClaimableEth({ player: address }),
    readAfkingFunding(address),
    readCoinflipDisplaySnapshot({ player: address }),
  ]);
  const values = reads.map((result) => result.status === 'fulfilled' ? result.value : null);
  return {
    address,
    walletEthWei: amount(values[0]),
    claimableEthWei: amount(values[1]),
    afkingEthWei: amount(values[2]),
    walletFlipWei: amount(values[3]?.balances?.flipBalance),
    claimableFlipWei: amount(values[3]?.claimableWei),
  };
}

/** A null reason means the exact preset can be funded with the known sources. */
export function recordBountyUnavailableReason(quote, {
  connected,
  acting,
  mode,
  funds,
  gameState,
} = {}) {
  if (!connected) return 'Connect your wallet to take a record shot.';
  const owner = String(connected).toLowerCase();
  if (mode !== 'self' || String(acting || '').toLowerCase() !== owner) {
    return 'Switch to your connected account to take a record shot.';
  }
  if (!quote || amount(quote.costWei) == null || amount(quote.costWei) <= 0n) {
    return 'The live record target or ticket price is loading.';
  }
  if (!gameState) return 'Game status is loading.';
  if (gameState.gameOver || gameState.phase === 'GAMEOVER' || gameState.livenessTriggered) {
    return 'The game has ended.';
  }
  // Ordinary ETH purchases and coinflip deposits can cross an RNG lock.
  // Do not disable them just because a drawing is in progress.
  if (!funds || String(funds.address || '').toLowerCase() !== owner) {
    return 'Your balances are loading.';
  }
  const wallet = amount(funds.walletEthWei);
  if (wallet == null) return 'Your ETH balance is loading.';
  if (wallet === 0n) return 'Wallet ETH is needed for transaction fees.';
  if (quote.kind === RECORD_KIND_FLIP) {
    const liquid = amount(funds.walletFlipWei);
    const claimable = amount(funds.claimableFlipWei);
    if ((liquid ?? 0n) + (claimable ?? 0n) >= quote.costWei) return null;
    return liquid == null || claimable == null
      ? 'Your FLIP balance is loading.'
      : 'Not enough spendable FLIP to reach this bounty.';
  }
  const useAfking = quote.kind === RECORD_KIND_BUY || quote.kind === RECORD_KIND_LUCKBOX;
  const payment = purchaseFundingPayment(
    quote.costWei,
    amount(funds.claimableEthWei) ?? 0n,
    amount(funds.afkingEthWei) ?? 0n,
    { useClaimable: true, useAfking },
  );
  // Equality leaves no native ETH for a transaction fee, even if the rest
  // comes from claimable winnings or prepaid AFKing funds.
  if (wallet > payment.msgValueWei) return null;
  if (amount(funds.claimableEthWei) == null
    || (useAfking && amount(funds.afkingEthWei) == null)) return 'Your ETH funds are loading.';
  return 'Not enough spendable ETH to reach this bounty and pay transaction fees.';
}
